/** 多库 key：legacy 库 id "default" 不加前缀（WeebPaint 存量缓存零迁移）。 */
export const thumbKeyFor = (galleryId, fullName) => (galleryId === "default" ? fullName : `${galleryId}:${fullName}`);
export function createThumbCache(deps) {
    const now = deps.now ?? (() => Date.now());
    const stats = { hits: 0, misses: 0, errors: 0 };
    const config = { skipCache: false };
    const listeners = new Set();
    async function read(name) {
        try {
            const v = await deps.store.get(deps.keyOf(name));
            return v && v.blob && v.token ? v : null;
        }
        catch {
            return null;
        }
    }
    async function write(name, token, blob) {
        try {
            await deps.store.set(deps.keyOf(name), { token, blob, at: now() });
        }
        catch (e) {
            deps.report?.(new Error("[thumb-cache] write failed: " + String(e)));
        }
    }
    return {
        read, write,
        async invalidate(name) {
            const key = deps.keyOf(name);
            try {
                await deps.store.delete(key);
            }
            catch { /* best-effort */ }
            for (const fn of listeners) {
                try {
                    fn(key);
                }
                catch { /* listener 自理 */ }
            }
        },
        onInvalidated(fn) { listeners.add(fn); return () => { listeners.delete(fn); }; },
        async getOrFetch(name, token, source) {
            if (!config.skipCache) {
                const c = await read(name);
                if (c && c.token === token) {
                    stats.hits++;
                    return { blob: c.blob, fromCache: true };
                }
            }
            stats.misses++;
            try {
                const blob = await deps.fetch(name, source);
                if (!config.skipCache)
                    void write(name, token, blob);
                return { blob, fromCache: false };
            }
            catch (e) {
                stats.errors++;
                if (!config.skipCache) {
                    const stale = await read(name);
                    if (stale)
                        return { blob: stale.blob, fromCache: true };
                } // 退旧图但不写缓存
                throw e;
            }
        },
        async clear() { const n = await deps.store.clear(); stats.hits = stats.misses = stats.errors = 0; return n; },
        stats, config,
    };
}
